{
  "master_id": "nelson-faria",
  "work_id": "brazilian-guitar-book",
  "usage_notes": [
    {
      "chord_quality": "dom7",
      "function_role": "baiao-modal-tonic",
      "narrative": "For dom7 chords in baiao, Faria prescribes practicing all patterns against a 'static seventh chord (mixolydian mode)' -- the dom7 is the modal tonic of the style, not a functional dominant. The bass plays a syncopated pedal tone while the upper voices land on the beat, inverting the samba texture. Chapter 5, p. 121.",
      "source_principle_ids": [
        "nelson-faria:brazilian-guitar-book:style-rhythmic-cell",
        "nelson-faria:brazilian-guitar-book:two-layer-texture"
      ],
      "source_work_id": "brazilian-guitar-book",
      "references": [
        {
